const PptxGenJS = require('pptxgenjs');
const pres = new PptxGenJS();
pres.layout = 'LAYOUT_16x9';

// Slide 1 - Title
const s1 = pres.addSlide();
s1.addText('团队协作', { x: 0.8, y: 1.5, w: 8.4, fontSize: 40, bold: true, color: '1B4F72', align: 'center' });
s1.addText('打造高效、信任、持续成长的团队', { x: 0.8, y: 2.8, w: 8.4, fontSize: 20, color: '555555', align: 'center' });

// Slide 2 - Why teamwork matters
const s2 = pres.addSlide();
s2.addText('为什么团队协作至关重要', { x: 0.5, y: 0.3, w: 9, fontSize: 28, bold: true, color: '1B4F72' });
s2.addText('• 复杂问题需要多元视角与跨职能能力\n• 协作能将个人产出放大为系统性成果\n• 高信任团队决策更快、试错成本更低\n• 员工在协作环境中敬业度与留存率更高', { x: 0.5, y: 1.2, w: 9, fontSize: 18, lineSpacingMultiple: 1.5 });

// Slide 3 - Core pillars
const s3 = pres.addSlide();
s3.addText('高效协作的四大支柱', { x: 0.5, y: 0.3, w: 9, fontSize: 28, bold: true, color: '1B4F72' });
s3.addText('1. 清晰目标 — 共同愿景 + 可衡量的里程碑\n2. 开放沟通 — 信息透明、反馈及时、心理安全\n3. 角色明确 — 权责对等、减少灰色地带\n4. 信任文化 — 允许犯错、鼓励求助、兑现承诺', { x: 0.5, y: 1.2, w: 9, fontSize: 18, lineSpacingMultiple: 1.5 });

// Slide 4 - Practical methods
const s4 = pres.addSlide();
s4.addText('落地实践方法', { x: 0.5, y: 0.3, w: 9, fontSize: 28, bold: true, color: '1B4F72' });
s4.addText('• 每日站会 / 周同步：对齐进度、暴露阻塞\n• RACI 矩阵：每项任务明确负责人与审批人\n• 回顾会议：每迭代复盘，沉淀可执行改进项\n• 共享文档 & 异步更新：减少无效会议\n• 结对工作 / 轮岗：打破知识孤岛', { x: 0.5, y: 1.2, w: 9, fontSize: 18, lineSpacingMultiple: 1.5 });

// Slide 5 - Takeaways
const s5 = pres.addSlide();
s5.addText('关键要点与行动号召', { x: 0.5, y: 0.3, w: 9, fontSize: 28, bold: true, color: '1B4F72' });
s5.addText('✓ 从"我"到"我们"：把目标共识放在分工之前\n✓ 建立反馈节奏：每周至少一次结构化回顾\n✓ 投资信任：领导者先示弱，团队才敢坦诚\n✓ 工具服务于流程，而非替代沟通\n\n👉 本周行动：选一个痛点，发起一次 30 分钟回顾', { x: 0.5, y: 1.2, w: 9, fontSize: 18, lineSpacingMultiple: 1.5 });

pres.writeFile({ fileName: '/workspace/团队协作.pptx' }).then(() => console.log('done'));
